#' Gene Set Enrichment Analysis (GSEA) for gene scores
#'
#' Perform Gene Set Enrichment Analysis using gene scores derived from an edgeR
#' DGEGLM object. `nproc` set to 1 within fgsea::fgsea
#'
#' @param res edgeR DGEGLM object, typically generated by glmQLFTest().
#' @param genesets A list of gene sets for GSEA analysis.
#'
#' @return A named list containing GSEA results for each gene set.
#'
#' @importFrom edgeR topTags
#' @importFrom dplyr mutate group_by slice_max ungroup select arrange
#' @importFrom tibble deframe
#' @importFrom purrr map
#' @importFrom fgsea fgsea
#'
#' @examples
#' # Example usage:
#' # res <- ... # edgeR DGEGLM object
#' # genesets <- list(h = laf::msigdb_h, c2 = laf::msigdb_c2)
#' # gsea_res <- gsea_gene_score(res, genesets)
#'
#' @export
gsea_gene_score <- function(res, genesets){

  # prepare geneset from edgeR DGEGLM object, probably created by glmQLFTest()
  geneStat <- edgeR::topTags(res, n = Inf) |>
    as.data.frame() |>
    dplyr::mutate(stat = sign(logFC) * -log10(FDR)) |>
    dplyr::mutate(absstat = abs(stat)) |>
    dplyr::group_by(gene_name) |>
    dplyr::slice_max(absstat, n = 1) |>
    dplyr::ungroup() |>
    dplyr::select(gene_name, stat) |>
    dplyr::arrange(desc(stat)) |>
    tibble::deframe()


  gsea_res <- purrr::map(
    genesets,
    \(x) fgsea::fgsea(x, stats = geneStat, nproc = 1)
  )

  names(gsea_res) <- names(genesets)

  return(gsea_res)
}
